{
  "items": [
    {
      "name": "AddMonoidAlgebra.supDegree_eq_of_max",
      "module_name": "Mathlib.Algebra.MonoidAlgebra.Degree",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} {A : Type u_3} {B : Type u_5} [inst : Semiring R] [inst_1 : SemilatticeSup B] [inst_2 : OrderBot B]\n  {D : A → B} [inst_3 : AddZeroClass A] {p : AddMonoidAlgebra R A} {b : B},\n  b ∈ Set.range D → Function.invFun D b ∈ p.support → (∀ a ∈ p.support, D a ≤ b) → AddMonoidAlgebra.supDegree D p = b"
    },
    {
      "name": "sup_eq_of_isMaxOn",
      "module_name": "Mathlib.Order.Filter.Extr",
      "kind": "theorem",
      "type": "∀ {α : Type u} {β : Type v} [inst : SemilatticeSup β] [inst_1 : OrderBot β] {D : α → β} {s : Finset α} {a : α},\n  a ∈ s → IsMaxOn D (↑s) a → s.sup D = D a"
    },
    {
      "name": "iSup",
      "module_name": "Mathlib.Order.SetNotation",
      "kind": "definition",
      "type": "{α : Type u} → {ι : Sort v} → [SupSet α] → (ι → α) → α"
    },
    {
      "name": "Polynomial.degree_sum_le",
      "module_name": "Mathlib.Algebra.Polynomial.Degree.Definitions",
      "kind": "theorem",
      "type": "∀ {R : Type u} [inst : Semiring R] {ι : Type u_1} (s : Finset ι) (f : ι → Polynomial R),\n  (∑ i ∈ s, f i).degree ≤ s.sup fun b => (f b).degree"
    },
    {
      "name": "AddMonoidAlgebra.supDegree_eq_of_isMaxOn",
      "module_name": "Mathlib.Algebra.MonoidAlgebra.Degree",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} {A : Type u_3} {B : Type u_5} [inst : Semiring R] [inst_1 : SemilatticeSup B] [inst_2 : OrderBot B]\n  {D : A → B} {p : AddMonoidAlgebra R A} {a : A},\n  a ∈ p.support → IsMaxOn D (↑p.support) a → AddMonoidAlgebra.supDegree D p = D a"
    },
    {
      "name": "Polynomial.supDegree_eq_natDegree",
      "module_name": "Mathlib.Algebra.Polynomial.Degree.Support",
      "kind": "theorem",
      "type": "∀ {R : Type u} [inst : Semiring R] (p : Polynomial R), AddMonoidAlgebra.supDegree id p.toFinsupp = p.natDegree"
    },
    {
      "name": "Polynomial.height_map_C",
      "module_name": "Mathlib.RingTheory.KrullDimension.Polynomial",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} [inst : CommRing R] [IsNoetherianRing R] (p : Ideal R) [p.IsMaximal],\n  (Ideal.map Polynomial.C p).height = p.height"
    },
    {
      "name": "AddMonoidAlgebra.supDegree_sum_lt",
      "module_name": "Mathlib.Algebra.MonoidAlgebra.Degree",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} {A : Type u_3} {B : Type u_5} [inst : Semiring R] [inst_1 : LinearOrder B] [inst_2 : OrderBot B]\n  {D : A → B} {ι : Type u_7} {s : Finset ι} {f : ι → AddMonoidAlgebra R A},\n  s.Nonempty →\n    ∀ {b : B}, (∀ i ∈ s, AddMonoidAlgebra.supDegree D (f i) < b) → AddMonoidAlgebra.supDegree D (∑ i ∈ s, f i) < b"
    }
  ]
}
